class AliasBadge:public QStyledItemDelegate{
public:using QStyledItemDelegate::QStyledItemDelegate;
 void paint(QPainter* p,const QStyleOptionViewItem& input,const QModelIndex& index)const override{
  auto model=static_cast<const MessageModel*>(index.model());if(!model->glacier||index.data().toString().isEmpty()){QStyledItemDelegate::paint(p,input,index);return;}
  QStyleOptionViewItem option(input);initStyleOption(&option,index);QString text=option.text;option.text.clear();auto style=option.widget?option.widget->style():QApplication::style();style->drawControl(QStyle::CE_ItemViewItem,&option,p,option.widget);
  QColor color=model->colors.value(index.siblingAtColumn(0).data().toString(),QColor("#15803D"));if(!color.isValid())color=QColor("#15803D");QColor background=QColor::fromRgbF(.84+.16*color.redF(),.84+.16*color.greenF(),.84+.16*color.blueF());QColor ink=color;while(ink.lightnessF()>.32)ink=ink.darker(120);
  p->save();QFont font=option.font;font.setBold(true);p->setFont(font);int width=qMin(option.rect.width()-8,QFontMetrics(font).horizontalAdvance(text)+16);QRect badge(option.rect.left()+4,option.rect.top()+4,qMax(0,width),option.rect.height()-8);p->setPen(Qt::NoPen);p->setBrush(background);p->drawRoundedRect(badge,3,3);p->setPen(ink);p->drawText(badge.adjusted(7,0,-3,0),Qt::AlignVCenter,QFontMetrics(font).elidedText(text,Qt::ElideRight,qMax(0,width-10)));p->restore();
 }
};
